head.script:
scwin.onpageload = function() {
	map1.checkResize = function() {
    try {
    //debugger;
        if (this.render) {
            var nWidth = this.render.offsetWidth;
            var nHeight = this.render.offsetHeight;
            if(this.resizeObj) {
                if (nWidth > 0 && nHeight > 0) {
                    if (this.currentMap === "" && this.resizeObj.width == 0 && this.resizeObj.height == 0) {
                        this._marker_tooltip = this.getElementById(this.id + "_marker_tooltip");
                        this.createMap({
                            "width": this.render.offsetWidth,
                            "height": this.render.offsetHeight,
                            "topoFile": this.getDataMapPath(this.options.startMap),
                            "topoObj": this.options.startMap
                        });
                    }
                }
            }
            this.resizeObj = {
                width: nWidth,
                height: nHeight
            };
        }
    } catch (e) {
        WebSquare.exception.printStackTrace(e, null, this);
    }
};
};
